    globalTotal = globalTotal + i
}
print(globalTotal)

float b = 2.5km
int a = 500m
var z = b + a:!
print(z)

var x = 10
var y = 3
print(x % y)

if (x > y && y > 0) {
    print(1)
} else {
    print(0)
}

