    // Ownership in property accessors (SPEC 2.2). Release also reads the destroyed objects (DestroyedException); #performance checks nothing there
    // (SPEC 2.5: undefined, natively a read of freed memory) - its run leaves those reads out, the order of the destructors shows the same ownership.
    // (Not Debug: it adds warnings for the fields that outlive their object.)
    const string accessorOwnership = """
        class Item {
            string n
            construct(string n) { this.n = n }
            destruct() { print("destroy " + this.n) }
        }
        class Node { Item child }
        class Other {
            Item kept
            Item Slot { get { return this.kept } set { this.kept = value } }
            Item AutoSlot { get; set; }
        }
        class Holder {
            Item cache
            Item other
            int arr[]
            Node node
            Item slot
            Other peer
            construct() { this.node = new Node(); this.peer = new Other() }
            Item Slot { get { return this.slot } set { this.slot = value } }
            // field of this (explicit and implicit), in an inner block
            int Field { get { var it = new Item("field"); this.cache = it; if (true) { var x = new Item("inner"); other = x } return 1 } }
            // return wins: the returned object goes to the caller (directly and read back from the field)
            Item Ret { get { var it = new Item("ret"); this.cache = it; return it } }
            Item RetField { get { var it = new Item("retfield"); this.other = it; return this.other } }
            // property of this and of another object, auto-property
            int Prop { get { var it = new Item("prop"); this.Slot = it; return 2 } }
            int PeerProp { get { var it = new Item("peer"); this.peer.Slot = it; return 3 } }
            int PeerAuto { get { var it = new Item("auto"); this.peer.AutoSlot = it; return 4 } }
            // a field of a field: no move (only fields of this)
            int Nested { get { var it = new Item("nested"); this.node.child = it; return 5 } }
            // an exception after the assignment: the field keeps the object
            int Throws { get { var it = new Item("throws"); this.cache = it; throw new ArgumentException("boom") } }
            // arrays too
            int Array { get { var a = new int[3]; a[0] = 42; this.arr = a; return a.Length } }
            // setter: field and forwarding to another property
            int Make { get { return 0 } set { var it = new Item("made " + value); this.cache = it } }
            int Forward { get { return 0 } set { var it = new Item("fwd " + value); this.peer.Slot = it } }
            // return of something else in a try/finally
            Item Fin { get { var it = new Item("fin"); try { this.other = it; return it } finally { print("finally: " + (it is from this)) } } }
            // a normal method: unchanged (the object dies with the call)
            undefined Method() { var it = new Item("method"); this.cache = it }
        }
        var h = new Holder()
        print("field: " + h.Field + " " + (h.cache is from h) + " " + (h.other is from h) + " " + h.other.n)
        var r = h.Ret
        print("ret: " + (r is from h) + " " + (h.cache == r))
        var rf = h.RetField
        print("retfield: " + (rf is from h) + " " + h.other.n)
        print("prop: " + h.Prop + " " + (h.slot is from h) + " " + h.slot.n)
        print("peer: " + h.PeerProp + " " + (h.peer.kept is from h.peer) + " " + h.peer.kept.n)
        print("auto: " + h.PeerAuto + " " + (h.peer.AutoSlot is from h.peer) + " " + h.peer.AutoSlot.n)
        print("nested: " + h.Nested)
        try { print(h.node.child.n) } catch (DestroyedException e) { print("nested destroyed") }
        try { print(h.Throws) } catch (ArgumentException e) { print("caught " + e.message + " " + (h.cache is from h) + " " + h.cache.n) }
        print("array: " + h.Array + " " + h.arr[0])
        h.Make = 7
        print("make: " + (h.cache is from h) + " " + h.cache.n)
        h.Forward = 8
        print("forward: " + (h.peer.kept is from h.peer) + " " + h.peer.kept.n)
        var f = h.Fin
        print("fin: " + (f is from h) + " " + f.n)
        {
            var outside = new Item("outside")
            h.Slot = outside
            print("outside: " + (h.slot is from h))
        }
        try { print(h.slot.n) } catch (DestroyedException e) { print("outside destroyed") }
        h.Method()
        try { print(h.cache.n) } catch (DestroyedException e) { print("method destroyed") }
        print("end")
        """;
    string[] accessorExpected = new[] { "field: 1 True True inner", "ret: False True", "retfield: False retfield", "prop: 2 True prop", "peer: 3 True peer", "auto: 4 True auto", "destroy nested", "nested: 5", "nested destroyed", "caught boom True throws", "array: 3 42", "make: True made 7", "forward: True fwd 8", "finally: False", "fin: False fin", "outside: False", "destroy outside", "outside destroyed", "destroy method", "method destroyed", "end", "destroy peer", "destroy auto", "destroy fwd 8", "destroy field", "destroy inner", "destroy prop", "destroy throws", "destroy made 7", "destroy ret", "destroy retfield", "destroy fin" };
    string[] accessorDeadReads = { "try { print(h.node.child.n) } catch (DestroyedException e) { print(\"nested destroyed\") }", "try { print(h.slot.n) } catch (DestroyedException e) { print(\"outside destroyed\") }", "try { print(h.cache.n) } catch (DestroyedException e) { print(\"method destroyed\") }" };
    CheckPerf("Ownership in Property-Accessoren (SPEC 2.2): Feld von this, Property, Return gewinnt, Ausnahme, Setter, normale Methode unveraendert",
        accessorOwnership, accessorExpected, new[] { VmExecutionMode.Release });
    CheckPerf("Ownership in Property-Accessoren (SPEC 2.2): dasselbe ohne Zugriffe auf zerstoerte Objekte (#performance prueft sie nicht)",
        accessorDeadReads.Aggregate(accessorOwnership, (text, read) => text.Replace(read, "")),
        accessorExpected.Where(l => !l.EndsWith(" destroyed")).ToArray(), new[] { VmExecutionMode.Performance });

    CheckPerf("Objekte: Ownership und Destruktor pro Schleifendurchlauf", """
        class D { int id; construct(int id) { this.id = id } destruct() { print("d" + this.id) } }
        for (var i = 0; i < 3; i = i + 1) { var d = new D(i) }
        print("ende")
        """, new[] { "d0", "d1", "d2", "ende" });

    CheckPerf("Arrays: Lesen, Schreiben, Grenzen, byte-Puffer, Strings", """
        var a = new int[3]
        a[0] = 10; a[1] = 20; a[2] = a[0] + a[1]
        print(a[2])
        try { print(a[3]) } catch (IndexOutOfBoundsException e) { print("aussen") }
        try { a[-1] = 1 } catch (IndexOutOfBoundsException e) { print("aussen2") }
        var b = new byte[2]
        b[1] = 200
        print(b[1])
        print("hey"[1])
        """, new[] { "30", "aussen", "aussen2", "200", "e" }, new[] { VmExecutionMode.Debug, VmExecutionMode.Release });

    Console.WriteLine(perfFailures == 0 ? "Alle VM-Optimierungs-Pruefungen bestanden." : $"FEHLER: {perfFailures} Pruefung(en) fehlgeschlagen.");
}

Console.WriteLine();
Console.WriteLine("=== Kopieren: flat x / copy x (SPEC 2.4) ===");
{
    int cloneFailures = 0;

    List<string> RunClone(string script)
    {
        var lines = new List<string>();
        var program = Parser.ParseMultiple(Preprocessed(Directory.GetCurrentDirectory(), fire.Standard.Prelude.Source, script));
        var natives = new NativeRegistry();
        natives.Register("print", args => { lines.Add(args[0].ToString()); return Value.MakeUndefined(); });
        natives.RegisterBaseTypeNatives();
        var resolveResult = Resolver.Resolve(program, natives.Names);
        var compiled = Compiler.Compile(program, resolveResult, natives);
        var vm = new VM(compiled.TopLevel, new Scope(null, isGlobal: true), natives, compiled.Classes);
        vm.Run();
        if (vm.UnhandledException != null)
            lines.Add("UNBEHANDELT: " + new UncaughtScriptException(vm.UnhandledException).Message);
        return lines;
    }

    void CheckClone(string title, string script, params string[] expected)
    {
        string[] actual;
        try { actual = RunClone(script).ToArray(); }
        catch (Exception ex) { actual = new[] { "AUSNAHME: " + ex.Message }; }
        bool ok = actual.SequenceEqual(expected);
        if (!ok) cloneFailures++;
        Console.WriteLine(ok ? $"OK: {title}" : $"FEHLER: {title}\n  erwartet: {string.Join(" | ", expected)}\n  erhalten: {string.Join(" | ", actual)}");
    }

    void CheckCloneError(string title, string script, string fragment)
    {
        string actual;
        try { actual = "kein Fehler: " + string.Join(" | ", RunClone(script)); }
        catch (Exception ex) { actual = ex.Message; }
        bool ok = actual.Contains(fragment);
        if (!ok) cloneFailures++;
        Console.WriteLine(ok ? $"OK: {title} -> {actual}" : $"FEHLER: {title}\n  erwartet: ...{fragment}...\n  erhalten: {actual}");
    }

    const string cloneClasses = """
        class Item {
            int n
            construct(int n) { this.n = n }
            destruct() { print("~I" + this.n) }
        }
        class Box {
            string name
            int size
            Item item
            Box other
            Item list[]
            int Extra { get; set; }
            construct(string name) { this.name = name; this.size = 1 }
            destruct() { print("~B" + this.name) }
        }

        """;

    CheckClone("flat: Objekt selbst und Werte kopiert, Referenzen bleiben", cloneClasses + """
        var a = new Box("a")
        a.item = new Item(1)
        a.Extra = 5
        var f = flat a
        f.name = "f"
        f.size = 7
        f.Extra = 6
        print(a.name + a.size + a.Extra)
        print(f.name + f.size + f.Extra)
        print(f.item == a.item)
        print(f == a)
        f.item.n = 9
        print(a.item.n)
        """, "a15", "f76", "True", "False", "9", "~Ba", "~I9", "~Bf");

    CheckClone("copy: Tiefenkopie, Kopie ist unabhaengig", cloneClasses + """
        var a = new Box("a")
        a.item = new Item(1)
        var d = copy a
        d.item.n = 99
        d.name = "d"
        print(a.item.n + " " + d.item.n)
        print(d.item == a.item)
        print(a.name)
        """, "1 99", "False", "a", "~Ba", "~I1", "~Bd", "~I99");

    CheckClone("copy: gemeinsame Referenz bleibt gemeinsam, Zyklus bleibt Zyklus", cloneClasses + """
        var shared = new Item(5)
        var x = new Box("x")
        x.item = shared
        x.other = new Box("y")
        x.other.item = shared
        x.other.other = x
        var c = copy x
        print(c.item == c.other.item)
        print(c.item == shared)
        print(c.other.other == c)
        print(c.other.other == x)
        print(c.other != x.other)
        """, "True", "False", "True", "False", "True", "~I5", "~Bx", "~By", "~Bx", "~By", "~I5");

    CheckClone("Arrays: flat teilt die Elemente, copy kopiert sie; Array als Operand", cloneClasses + """
        var b = new Box("arr")
        b.list = [new Item(1), new Item(2)]
        var f = flat b
        var c = copy b
        c.list[0].n = 10
        f.list[1].n = 20
        print(b.list[0].n + " " + b.list[1].n + " " + c.list[0].n)
        print(f.list == b.list)
        print(c.list == b.list)
        var nums = [1, 2, 3]
        var n1 = flat nums
        var n2 = copy nums
        n1[0] = 100
        n2[1] = 200
        print(nums[0] + " " + nums[1] + " " + n1[0] + " " + n2[1])
        var bytes = "AB".ToBytes()
        var b2 = copy bytes
        b2[0] = 67
        print(bytes[0] + " " + b2[0])
        """, "1 20 10", "True", "False", "1 2 100 200", "65 67", "~Barr", "~I1", "~I20", "~Barr", "~Barr", "~I10", "~I2");

    CheckClone("Werte: nichts zu kopieren", """
        print(copy 5)
        print(flat "text")
        print(copy 2.5)
        print(flat true)
        var u = copy undefined
        print(u == undefined)
        """, "5", "text", "2.5", "True", "True");

    CheckClone("Parameter: die Funktion arbeitet auf einer Kopie", cloneClasses + """
        var Touch = func (b) => { b.name = "geaendert"; b.item.n = 77; return b.name }
        var a = new Box("a")
        a.item = new Item(1)
        print(Touch(flat a))
        print(a.name + " " + a.item.n)
        a.name = "a"
        a.item.n = 1
        print(Touch(copy a))
        print(a.name + " " + a.item.n)
        """, "~Bgeaendert", "geaendert", "a 77", "~Bgeaendert", "~I77", "geaendert", "a 1", "~Ba", "~I1");

    CheckClone("Owner: Kopie gehoert dem Scope und wird mit ihm zerstoert (Besitz bleibt erhalten)", cloneClasses + """
        {
            var a = new Box("a")
            a.item = new Item(1)
            var f = flat a
            f.name = "f"
            var d = copy a
            d.name = "d"
            print("|")
        }
        print("danach")
        """, "|", "~Ba", "~I1", "~Bf", "~Bd", "~I1", "danach");

    CheckClone("Owner: direkt einem Feld zugewiesen gehoert die Kopie dem Zielobjekt", cloneClasses + """
        {
            var src = new Box("src")
            src.item = new Item(3)
            var holder = new Box("holder")
            holder.other = copy src
            holder.other.name = "kopie"
            holder.item = flat src.item
            print("|")
        }
        print("danach")
        """, "|", "~Bsrc", "~I3", "~Bholder", "~Bkopie", "~I3", "~I3", "danach");

    CheckClone("Owner ausserhalb der Kopie: die Kopie gehoert dem Scope", cloneClasses + """
        {
            var owner = new Box("own")
            owner.item = new Item(7)
            var holder = new Box("holder")
            holder.item = owner.item
            var c = copy holder
            c.item.n = 8
            print(holder.item.n + " " + c.item.n)
        }
        print("danach")
        """, "7 8", "~Bown", "~I7", "~Bholder", "~Bholder", "~I8", "danach");

    CheckClone("Kopie laeuft ohne Konstruktor, der Destruktor laeuft fuer die Kopie", """
        class K {
            int v
            construct(int v) { this.v = v; print("ctor") }
            destruct() { print("dtor" + this.v) }
        }
        {
            var k = new K(1)
            var c = copy k
            var f = flat k
            c.v = 2
            print("kopiert")
        }
        """, "ctor", "kopiert", "dtor1", "dtor2", "dtor1");

    CheckClone("Kopie in Methode und return: Ownership geht an den Aufrufer", cloneClasses + """
        class Maker { static Box Make(Box src) { var c = copy src; c.name = "made"; return c } }
        var s = new Box("s")
        s.item = new Item(4)
        {
            var m = Maker.Make(s)
            print(m.name + " " + m.item.n)
        }
        print("danach")
        """, "made 4", "~Bmade", "~I4", "danach", "~Bs", "~I4");

    CheckClone("Actor: in der Tiefe geteilt", """
        actor Counter { int n; construct() { this.n = 0 } Inc() { this.n = this.n + 1 } }
        class Holder { Counter c; construct() { this.c = new Counter() } }
        var h = new Holder()
        var d = copy h
        var f = flat h
        print(d.c == h.c)
        print(f.c == h.c)
        """, "True", "True");

    CheckCloneError("Actor als Operand", """
        actor Counter { int n; construct() { this.n = 0 } }
        var c = new Counter()
        var d = copy c
        """, "actor");

    CheckCloneError("zerstoertes Objekt", cloneClasses + """
        var leaked = new Box("x")
        {
            var t = new Box("t")
            leaked = t
            delete t
        }
        var d = copy leaked
        """, "destroyed");

    CheckCloneError("Kopier-Praefix ohne Operand", "var x = copy", "Unexpected token");

    Console.WriteLine(cloneFailures == 0 ? "Alle Kopier-Pruefungen bestanden." : $"FEHLER: {cloneFailures} Pruefung(en) fehlgeschlagen.");
}

