// ---------------------------------------------------------------------------
// UI library (#import "ui"): headless - real framebuffer/console/WindowManager, only the renderer is a dummy
// ---------------------------------------------------------------------------
{
    Console.WriteLine();
    Console.WriteLine("=== UI-Bibliothek ===");
    int uiFailures = 0;

    IReadOnlyDictionary<string, RuntimeClass>? uiClasses = null;

    // Runs `script` with graphics prelude + UI prelude. The window runs via the real WindowManager (event queue
    // included), only the renderer is `FakeRenderer`: `__TestEvent(type, ...)` stores an event that the next Tick fetches,
    // `__TestClose()` closes the window.
    List<string> RunUi(string script, VmExecutionMode mode)
    {
        var lines = new List<string>();
        var sources = new[] { fire.Standard.Prelude.Source, StdPrelude("graphics"), StdPrelude("windows"), StdPrelude("reflection"), StdPrelude("ui"), script };
        var alreadyIncluded = new HashSet<string>(StringComparer.OrdinalIgnoreCase);
        var program = Parser.ParseMultiple(sources.Select(src => Preprocessor.Process(src, Directory.GetCurrentDirectory(), alreadyIncluded)).ToList());
        var natives = new NativeRegistry();
        natives.Register("print", args => { lock (lines) lines.Add(args[0].ToString()); return Value.MakeUndefined(); });
        natives.RegisterBaseTypeNatives();

        // graphics and windows are the C library's (a copy of it, whose window the test drives: TestHostDisplay) - what a program runs on
        var renderer = new TestHostDisplay();
        var instance = fire.Compiler.GraphicsLibrary.Instance.Acquire() ?? throw new InvalidOperationException("the C library of graphics and windows cannot be built: " + fire.Compiler.GraphicsLibrary.Failure);
        instance.Attach(renderer);
        fire.Compiler.GraphicsLibrary.Register(natives, withWindows: true, instance: instance);
        ReflectionNatives.Register(natives);

        natives.Register("__TestClose", args => { renderer.Close(); return Value.MakeUndefined(); });
        var testClock = System.Diagnostics.Stopwatch.StartNew();
        natives.Register("__TestMillis", args => Value.MakeInt(testClock.ElapsedMilliseconds));
        natives.Register("__TestEvent", args =>
        {
            renderer.Push((int)args[0].AsInt(), args);
            return Value.MakeUndefined();
        });
        // Window.StartDrag: the answer of the desktop, and each call as a line of the output
        natives.Register("__TestDragAnswer", args => { renderer.DragAnswer = (int)args[0].AsInt(); return Value.MakeUndefined(); });
        natives.Register("__TestCanDrag", args => { renderer.CanDrag = args[0].AsBool(); return Value.MakeUndefined(); });
        renderer.Dragged = (text, files) => { lock (lines) lines.Add($"StartDrag [{text}] [{string.Join(",", files)}]"); };

        var resolveResult = Resolver.Resolve(program, natives.Names);
        var compiled = Compiler.Compile(program, resolveResult, natives);
        uiClasses = compiled.Classes;
        var vm = new VM(compiled.TopLevel, new Scope(null, isGlobal: true), natives, compiled.Classes, isMainThreadVm: true, executionMode: mode);
        try
        {
            using (PackageHost.Begin(null, null, libraries: new[] { instance.File })) vm.Run();   // (its end resets the copy: windows, framebuffers)
        }
        finally { instance.Dispose(); }
        if (vm.UnhandledException != null)
            lines.Add("UNBEHANDELT: " + new UncaughtScriptException(vm.UnhandledException).Message);
        return lines;
    }

    // ---- debugger: the variables have their names (globals, inner blocks, foreach), the field initialisers their line ----
    {
        string dbgScript = """
            class Rod {
                int length = Rod.Calc()
                static int Calc() { __dbgSnap(); return 4 }
            }
            var first = 1
            var r = new Rod()
            {
                var inner = 7
                foreach (k in [5]) {
                    __dbgSnap()
                }
            }
            """;
        var snaps = new List<string>();
        foreach (var mode in new[] { VmExecutionMode.Debug, VmExecutionMode.Release })
        {
            snaps.Clear();
            var natives = new NativeRegistry();
            natives.Register("__dbgSnap", args =>
            {
                var vm = VM.CurrentThreadVm!;
                string locals = string.Join(",", vm.DebugScopeChain().SelectMany(l => l.Variables).Select(v => v.Name + "=" + v.Value));
                string globals = string.Join(",", vm.DebugGlobals().Select(v => v.Name + "=" + v.Value));
                snaps.Add($"[{locals}] [{globals}] line {vm.CurrentLine}");
                return Value.MakeUndefined();
            });
            natives.RegisterBaseTypeNatives();
            var dbgProgram = Parser.ParseMultiple(new[] { fire.Standard.Prelude.Source, dbgScript }.Select(src => Preprocessor.Process(src, Directory.GetCurrentDirectory())).ToList());
            var dbgResolved = Resolver.Resolve(dbgProgram, natives.Names);
            var dbgCompiled = Compiler.Compile(dbgProgram, dbgResolved, natives);
            var dbgVm = new VM(dbgCompiled.TopLevel, new Scope(null, isGlobal: true), natives, dbgCompiled.Classes, isMainThreadVm: true, executionMode: mode);
            dbgVm.Run();
            var expected = new[] { "[] [first=1] line 3", "[k=5,inner=7] [first=1,r=<object Rod>] line 10" };
            bool ok = snaps.SequenceEqual(expected);
            Console.WriteLine(ok ? $"OK: Debugger: Variablen mit Namen (global, innere Bloecke, foreach) [{mode}]" : $"FEHLER: Debugger: Variablen mit Namen [{mode}]\n  erwartet: {string.Join(" | ", expected)}\n  erhalten: {string.Join(" | ", snaps)}");
            if (!ok) uiFailures++;
        }
    }

    uiDrawExpected = RunUi(uiDrawScript, VmExecutionMode.Release).ToArray();

    void CheckUi(string title, string script, string[] expected)
    {
        if (!TestSelected(title)) return;
        foreach (var mode in new[] { VmExecutionMode.Debug, VmExecutionMode.Release })
        {
            string[] actual;
            try { actual = RunUi(script, mode).ToArray(); }
            catch (Exception ex) { actual = new[] { "AUSNAHME: " + CompileErrors.Describe(ex) }; }
            bool ok = actual.SequenceEqual(expected);
            if (!ok) uiFailures++;
            Console.WriteLine(ok ? $"OK: {title} [{mode}]" : $"FEHLER: {title} [{mode}]\n  erwartet: {string.Join(" | ", expected)}\n  erhalten: {string.Join(" | ", actual)}");
        }
    }

    const string uiHead = """
        // GetPixel returns the colour value signed (32 bit); the colours of the UI library are unsigned values
        class Px { static int Get(console, int x, int y) { var v = console.GetPixel(x, y); if (v < 0) { v = v + 4294967296 } return v } }
        var fb = new Framebuffer(320, 200)
        var win = new Window(fb, "Test")
        var ui = new UI.Root(fb, win)

        """;

    CheckUi("Touch und Joystick: Ereignisse als Warteschlange, TouchMouse, Callbacks mit passender Parameterzahl", """
        var fb = new Framebuffer(100, 80)
        var win = new Window(fb, "Input")
        win.EnableEvents()
        print(win.TouchMouse)
        win.TouchMouse = false
        print(win.TouchMouse)
        __TestEvent(16, 3, 10.5, 20.5)
        __TestEvent(17, 3, 12.0, 22.0)
        __TestEvent(18, 3, 12.0, 22.0)
        __TestEvent(32, 7, 1, -0.5)
        __TestEvent(33, 7, 2)
        __TestEvent(34, 7, 2)
        __TestEvent(35, 7, 0, 5)
        __TestEvent(36, 7)
        __TestEvent(37, 7)
        win.Tick()
        var e = win.NextEvent()
        while (e != undefined) {
            var line = ""
            for (var i = 0; i < e.length; i++) { line = line + e[i] + " " }
            print(line)
            e = win.NextEvent()
        }
        print(win.RegisterTouchDown(func (int f, float x, float y, float p) => { }))
        print(win.RegisterTouchMove(func (int f, float x, float y, float p) => { }))
        print(win.RegisterTouchUp(func (int f, float x, float y, float p) => { }))
        print(win.RegisterJoystickAxis(func (int j, int a, float v) => { }))
        print(win.RegisterJoystickHat(func (int j, int h, int m) => { }))
        print(win.RegisterJoystickButtonDown(func (int j, int b) => { }))
        print(win.RegisterJoystickButtonUp(func (int j, int b) => { }))
        print(win.RegisterJoystickAdded(func (int j) => { }))
        print(win.RegisterJoystickRemoved(func (int j) => { }))
        """, new[] { "True", "False", "16 3 10 20 1 ", "17 3 12 22 1 ", "18 3 12 22 1 ", "32 7 1 -0.5 ", "33 7 2 ", "34 7 2 ", "35 7 0 5 ", "36 7 ", "37 7 ", "True", "True", "True", "True", "True", "True", "True", "True", "True" });

    CheckUi("Textfeld: Auswahl mit Shift und der Maus, Ctrl+A/C/X/V und Shift+Insert ueber die Zwischenablage, Tippen ersetzt die Auswahl, MaxLength", uiHead + """
        var tb = new UI.TextBox("Hallo Welt", 10, 10, 200, 24)
        ui.Add(tb)
        ui.Draw()
        ui.SetFocus(tb)
        print(Clipboard.HasText)
        __TestEvent(24, UI.Keys.Home(), 1)
        __TestEvent(24, UI.Keys.C(), 64)
        ui.Tick()
        print("[" + tb.SelectedText + "] " + Clipboard.GetText() + " " + Clipboard.HasText)
        __TestEvent(24, UI.Keys.End(), 0)
        for (var i = 0; i < 4; i++) { __TestEvent(24, UI.Keys.Left(), 2) }
