                for (var c = 0; c < 32; c = c + 8) {
                    var d = Math.Abs(((pa >> c) & 255) - ((pb >> c) & 255))
                    if (d > worst) { worst = d }
                }
            }
        }
        print("gpu " + (!b.Accelerated || worst <= 2) + " " + (b.Accelerated || Framebuffer.GpuError() != ""))
        """, new[] { "gpu True True" });
