                var bound = fire.UI.Markup.MarkupParser.Parse("<Window Class=\"B\" Width=\"200\" Height=\"100\"><Label Text=\"{Binding Name}\"/><Label Color=\"{Enum Colors.Red}\" Text=\"x\"/><Button OnClick=\"Nope\"/></Window>");
