        d.WriteString("eins")
        d.WriteString("zwei")
        print(d.WaitForString("ei"))
        print("[" + d.ReadString() + "]")
        var tries = 0
        while (!d.HasData() && tries < 200) { Sleep(TimeSpan.FromMilliseconds(10)); tries = tries + 1 }   // the echo of "zwei" arrives a moment later
        print("[" + d.ReadString() + "]")
        """, new[] { "True", "[nutzlast]", "True", "[ns]", "[zwei]" }, defaultId: "loopback:echo");

