// ---------------------------------------------------------------------------------------------------------------------------
// Native backend (fire.Native): the same source runs in the VM and as generated C++ - the output must be identical
// ---------------------------------------------------------------------------------------------------------------------------
nativeTests:
if (Environment.GetEnvironmentVariable("FIRE_TEST_NO_NATIVE") == "1") Console.WriteLine("(FIRE_TEST_NO_NATIVE: the native checks are skipped)");
else
{
    Console.WriteLine("=== Native-Backend: erzeugtes C++ gegen die VM ===");
    Console.WriteLine($"(bis zu {TestJobs.Count} Faelle zugleich (FIRE_TEST_JOBS), gebaut mit {NativeTestBuild.Opt} (FIRE_TEST_OPT){(NativeTestBuild.Ccache != null ? ", ccache" : "")})");
    // (the async reads of the output of processes complete on the thread pool: enough threads that a worker that waits for a process never waits for them)
    ThreadPool.GetMinThreads(out int minWorkers, out int minIo);
    ThreadPool.SetMinThreads(Math.Max(minWorkers, 8 * TestJobs.Count), Math.Max(minIo, 8 * TestJobs.Count));
    int natFailures = 0;
    void CheckNat(string title, bool ok, string? detail = null)
    {
        if (!ok) Interlocked.Increment(ref natFailures);
        Console.WriteLine(ok ? $"OK: {title}" : $"FEHLER: {title}" + (detail == null ? "" : $"\n{detail}"));
    }

    string? FindCxx()
    {
        foreach (var name in new[] { "g++", "clang++", "c++" })
        {
            try
            {
                using var p = System.Diagnostics.Process.Start(new System.Diagnostics.ProcessStartInfo(name, "--version") { RedirectStandardOutput = true, RedirectStandardError = true, UseShellExecute = false })!;
                p.WaitForExit();
                if (p.ExitCode == 0) return name;
            }
            catch (Exception) { }
        }
        return null;
    }

    var vmUnhandled = new Dictionary<string, string>();
    string vmOutput(string source)
    {
        // `terminate` and `catch threads/terminate` are process-wide state of the VM: an earlier case must not leave its handlers behind
        VM.ResetTerminateForTests();
        GlobalHandlers.ResetForTests();
        var lines = new List<string>();
        var session = RuntimeSession.Build(new[] { source }, VmExecutionMode.Release, args => { lines.Add(args[0].ToString()!); return Value.MakeUndefined(); });
        session.Run();
        // what the command line runner writes to stderr for an exception that nothing catches (an "Abbruch:" case compares it with the native program)
        if (session.VirtualMachine?.UnhandledException is { } unhandled) lock (vmUnhandled) vmUnhandled[source] = new UncaughtScriptException(unhandled).Message;
        return string.Join("\n", lines) + (lines.Count > 0 ? "\n" : "");
    }

    var natCases = new (string Name, string Source)[]
    {
        ("Ueberladung vorab gewaehlt (OverloadHint): statisch, Konstruktor, Objekt einer abgeleiteten Klasse, any zur Laufzeit", """
            class Animal { }
            class Dog : Animal { }
            class Show {
                static string Of(int x) { return "int" }
                static string Of(string s) { return "string" }
                static string Of(Animal a) { return "animal" }
                static string Of<T>(T x) { return "generic" }
                string Me(int x) { return "me int" }
                string Me(float f) { return "me float" }
                construct() { }
                construct(int a) { }
                construct(string s) { }
            }
            class SubShow : Show {
                override string Me(int x) { return "sub int" }
            }
            print(Show.Of(1))
            print(Show.Of("s"))
            print(Show.Of(new Dog()))
            print(Show.Of(2.5))
            var s = new Show(3)
            var t = new Show("x")
            print(s.Me(1) + " " + s.Me(1.5))
            Show sub = new SubShow()
            print(sub.Me(1) + " " + sub.Me(1.5))
            any v = "dyn"
            print(Show.Of(v))
            """),
        ("Ueberladung vorab gewaehlt: wechselnder Argumenttyp an derselben Stelle (any) waehlt jedes Mal richtig", """
            class Show {
                static string Of(int x) { return "int" }
                static string Of(string s) { return "string" }
                string Me(int x) { return "me int" }
                string Me(string s) { return "me string" }
                string made
                construct(int a) { this.made = "ctor int" }
                construct(string s) { this.made = "ctor string" }
            }
            var sh = new Show(1)
            for (int i = 0; i < 6; i++) {
                any x = i
                if (i % 2 == 1) { x = "odd" }
                print(Show.Of(x) + " / " + sh.Me(x) + " / " + new Show(x).made)
            }
            """),
        ("Ueberladung nach Typ: ref-Parameter, statisch und Instanz gemischt, Basistyp-Erweiterung, generic vor class vor any", """
            class Inc {
                static string Bump(ref int x) { x = x + 1; return "ref int" }
                static string Bump(string s) { return "string " + s }
                string Twice(ref float f) { f = f * 2.0; return "ref float" }
                string Twice(int i) { return "int" }
                construct() { }
                construct(ref int n) { n = n + 10 }
                construct(string s) { }
            }
            int a = 1
            print(Inc.Bump(a) + " " + a)
            print(Inc.Bump("q"))
            float g = 1.5
            var inc = new Inc()
            print(inc.Twice(g) + " " + g)
            print(inc.Twice(3))
            int k = 5
            var made = new Inc(k)
            print(k)

            class Mixed {
                static string Go(int x) { return "static int" }
                string Go(string s) { return "instance string" }
            }
            print(Mixed.Go(1))
            print(new Mixed().Go("s"))

            class extends string {
                string Tag(int n) { return this + "#" + n }
                string Tag(string s) { return this + "/" + s }
                string Tag<T>(T x) { return this + "?" }
            }
            print("a".Tag(1))
            print("b".Tag("c"))
            print("d".Tag(2.5))

            class Thing { }
            class Prio {
                static string P(class c) { return "class" }
                static string P<T>(T x) { return "generic" }
                static string Q(class c) { return "class" }
                static string Q(any x) { return "any" }
            }
            print(Prio.P(new Thing()))
            print(Prio.Q(new Thing()))
            print(Prio.Q(3))
            """),
        ("Ueberladung nach Typ: statisch - Basistypen, Klasse vor Basisklasse vor Interface vor generic vor any, int nach float", """
            interface IShape { float Area() }
            class Animal {
                string name
                construct(string n) { this.name = n }
            }
            class Dog : Animal {
                construct(string n) : base(n) { }
            }
            class Puppy : Dog {
                construct(string n) : base(n) { }
            }
            class Square : IShape {
                float Area() { return 4.0 }
            }
            class Show {
                static string Of(int x) { return "int " + x }
                static string Of(float x) { return "float " + x }
                static string Of(string x) { return "string " + x }
                static string Of(bool x) { return "bool " + x }
                static string Of(Animal a) { return "animal " + a.name }
                static string Of(Dog d) { return "dog " + d.name }
                static string Of(IShape s) { return "shape " + s.Area() }
                static string Of<T>(T x) { return "generic" }

                static string Num(float x) { return "float" }
                static string Num(any x) { return "any" }
            }
            print(Show.Of(1))
            print(Show.Of(1.5))
            print(Show.Of("a"))
            print(Show.Of(true))
            print(Show.Of(new Animal("rex")))
            print(Show.Of(new Dog("bello")))
            print(Show.Of(new Puppy("tiny")))
            print(Show.Of(new Square()))
            print(Show.Of('c'))
            print(Show.Num(3))
            print(Show.Num("x"))
            any v = 7
            print(Show.Of(v))
            """),
        ("Ueberladung nach Typ: DoThis<string>(x) meint die generische, Basis-/abgeleitete Klasse, Konstruktoren, any-Werte zur Laufzeit", """
            #strict
            class Util {
                static string DoThis(string s) { return "string" }
                static string DoThis<T>(T x) { return "generic" }
