                                try { throw new E1() }
                                catch (E1 e) { log = log + "c "; break 2 }
                                finally { log = log + "f1 " }
                            }
                        } finally { log = log + "f2 " }
                        log = log + "never "
                    }
                    return log
                }
                static string K() {
                    string log = ""
                    foreach (x in [1, 2]) {
                        foreach (y in [1, 2]) {
                            try { throw new E1() } catch (E1 e) { log = log + x + y + " "; continue 2 } finally { log = log + "f "; }
                        }
                    }
                    return log
                }
