                static int Bump(Item list[]) { list[1].v = list[1].v + 10; return list[1].v }
                static Item Make(int v) { return new Item(v) }
                static int Boom(int v) { if (v > 0) { throw new ArgumentException("boom " + v) }; return v }
                int factor = 3
