            }
            class Keeper {
                class items
                int count
                construct() { this.items = new class[4]; this.count = 0 }
                Add(class value) {
                    try value.TakeTo(this)
                    this.items[this.count] = value
                    this.count = this.count + 1
                }
            }
            class Holder {
                Keeper k
                List people
                construct() {
                    this.k = new Keeper()
