                print("in thread " + store.Count() + " " + store.Sum() + " first " + store.First().v + " slow " + store.Slow(21))
                try { store.Fail() } catch (ArgumentException e) { print("caught " + e.message) }
                store.SetCb(() => 8)
                print("cb " + store.cb())
                store.SetCb(g0)
                step = 1
