                construct(string s, int n) { this.name = s; this.n = n; this.tag = new Tag("t" + n) }
                int Sum() {
                    int r = 0
                    for (int k = 0; k < 20; k++) { r = r + this.name.Length + this.tag.label.Length }
                    return r
                }
            }
            var ch = new Channel<Item>(64)
