                    try {
                        for (int k = 0; k < 50; k++) { reads = reads + it.name.Length + it.n + it.Sum() }
                        string both = it.name + it.tag.label
                        reads = reads + both.Length
                    } catch (DestroyedException e) { reads = reads - 1 }
                }
                done.Send(seen)
            }
            for (int i = 0; i < 1500; i++) {
                if (true) {
                    var it = new Item("item" + i, i)
