            class Cache {
                static Node cached
                static Node Get() {
                    if (Cache.cached != undefined) { return Cache.cached }
                    var n = new Node(3)
                    n.TakeGlobal()
                    Cache.cached = n
                    n.a.v = 4
                    return n
                }
            }
            Node keep = undefined
            Node keep2 = undefined
            Node mineOnly = undefined
            var step = 0
