            while (step < 1) { Sleep(1ms) }
            Sleep(20ms)
            print("main " + Cache.cached.a.v + " " + keep.a.v + " " + keep.inner.a.v + " " + keep2.other.v + " " + (keep2.other is from keep2) + " " + (mineOnly == undefined))
