            class F {
              static Sum(ref int first, int n) {
                var t = 0
                unsafe {
                  int* p = &first
                  for (var i = 0; i < n; i++) { t = t + *p; p = p + 1 }
                }
                return t
              }
              static Zero(ref int first, int n) {
                unsafe {
                  int* p = &first
                  for (var i = 0; i < n; i++) { *p = 0; p = p + 1 }
                }
              }
              static Bytes(ref byte first, int n) {
                var t = 0
                unsafe {
                  byte* p = &first
                  for (var i = 0; i < n; i++) { t = t + *p; p = p + 1 }
                }
                return t
              }
            }
            var a = [1, 2, 3, 4, 5]
            print(F.Sum(a[1], 3))
            F.Zero(a[2], 2)
