            """),
        ("Circuits: Attached-Bauteile in fire und Bauteile an den simulierten Geraeten (GPIO-Leitung, I2C-ADC/DAC, SPI-Schieberegister)", """
            #import "circuits"
            class H { static float R(float v) { return Math.Round(v * 1000) / 1000 } }
            // a part in fire: drives its pin with a 1 kHz square wave
            class Blinker : Circuits.Attached {
                construct() : base("blink") { this.AddPin("out") }
                override undefined Update(float time) { this.DriveHigh(0, (Math.Floor(time * 2000)!int) % 2 == 0) }
            }
            var c = new Circuits.Circuit()
            var b = c.Add(new Blinker())
            var r = c.Add(new Circuits.Resistor(1kOhm))
            b.Pin(0).Connect(r.A)
            r.B.Connect(c.Ground)
            c.TimeStep = 10us
            c.Run(0.1ms)
            print("blink " + H.R(r.A.Raw()) + " V, " + H.R(b.CurrentAt(0) * 1000) + " mA")
            c.Run(0.5ms)
            print("blink " + H.R(r.A.Raw()) + " V")
            // the program drives GPIO line 3, the circuit has an LED on it
            var g = c.Add(new Circuits.GpioLine(3))
            var led = c.Add(new Circuits.Led("red"))
            var rl = c.Add(new Circuits.Resistor(100))
            g.P.Connect(rl.A)
            rl.B.Connect(led.A)
            led.B.Connect(c.Ground)
            var pin = new Gpio.Pin("sim", 3)
            pin.Output(true)
            c.Run(1ms)
            print("led " + led.IsOn + " at " + H.R(g.P.Raw()) + " V")
            pin.Write(false)
            c.Run(1ms)
            print("led " + led.IsOn)
            // a button of the circuit at line 4
            var g4 = c.Add(new Circuits.GpioLine(4))
            var vs = c.Add(new Circuits.VoltageSource(3.3V))
            var sw = c.Add(new Circuits.Switch(false))
            var pd = c.Add(new Circuits.Resistor(10kOhm))
            vs.B.Connect(c.Ground)
            vs.A.Connect(sw.A)
            sw.B.Connect(g4.P)
            pd.A.Connect(g4.P)
            pd.B.Connect(c.Ground)
            var button = new Gpio.Pin("sim", 4)
            button.Input()
            c.Run(1ms)
            print("button " + button.Read())
            sw.Closed = true
            c.Run(1ms)
            print("button " + button.Read())
            // I2C: an ADC measures a divider, a DAC puts out what the program writes
            var adc = c.Add(new Circuits.I2cAdc(0x48, 2, 5V))
            var adc16 = c.Add(new Circuits.I2cAdc(0x4A, 1, 5V, 12))
            var d1 = c.Add(new Circuits.Resistor(1kOhm))
            var d2 = c.Add(new Circuits.Resistor(1kOhm))
            var v5 = c.Add(new Circuits.VoltageSource(5V))
            v5.B.Connect(c.Ground)
            v5.A.Connect(d1.A)
            d1.B.Connect(d2.A)
            d2.B.Connect(c.Ground)
            d1.B.Connect(adc.In(1))
            d1.B.Connect(adc16.In(0))
            var dac = c.Add(new Circuits.I2cDac(0x60))
            var bus = new I2c.Bus("sim")
            bus.WriteRegister(0x60, 0, 51)
            c.Run(1ms)
            print("adc " + bus.ReadRegister(0x48, 0) + " " + bus.ReadRegister(0x48, 1) + " 12 bit " + (bus.ReadRegister(0x4A, 0) * 256 + bus.ReadRegister(0x4A, 1)))
            print("dac " + H.R(dac.Out(0).Raw()) + " V")
            // SPI: a shift register with outputs feeds one with inputs
            var so = c.Add(new Circuits.SpiShiftOut())
            var si = c.Add(new Circuits.SpiShiftIn())
            so.Q(0).Connect(si.D(7))
            so.Q(2).Connect(si.D(0))
            var spi = new Spi.Device("sim")
            var tx = new byte[1]
            tx[0] = 0xA5
            spi.Transfer(tx)
            c.Run(1ms)
            print("shift out " + so.Value + ", q0 " + H.R(so.Q(0).Raw()) + " V")
            var rx = spi.Transfer(tx)
            print("shift in " + rx[0])
            // the same from a drawing
            var d = new Circuits.Circuit("drawn")
            var s = d.Schematic
            s.Add("GpioLine", 0, 0, 4, 0, "line=7", "out7")
            s.Add("Resistor", 0, 0, 0, 8, "resistance=220")
            s.Add("Led", 0, 8, 0, 16, "", "d1")
            s.Add("Ground", 0, 16, 0, 20)
            s.Add("I2cAdc", 10, 0, 22, 0, "address=0x49;channels=2", "u1")
            s.Add("Rail", 10, 0, 6, 0, "voltage=2.5")
            var sr = s.Add("SpiShiftOut", 30, 0, 42, 0, "", "u2")
            var bad = s.Add("I2cDac", 30, 20, 42, 20, "address=0x99")
            d.TimeStep = 10us
            var pin7 = new Gpio.Pin("sim", 7)
            pin7.Output(true)
            d.Run(1ms)
            Circuits.Led d1led = s.Find("d1").part!Circuits.Led
            print("drawn: led " + d1led.IsOn + ", adc " + bus.ReadRegister(0x49, 0) + ", pins " + sr.PinCount + ", bad: " + bad.Error)
            """),
        ("Circuits: eine Schaltung laeuft neben dem Programm her (Simulation.Touch bei jedem Zugriff auf ein simuliertes Geraet)", """
            #import "circuits"
            class Counting : Simulation {
                int n = 0
                construct() : base() { }
                override undefined Advance() { this.n = this.n + 1 }
            }
            var counting = new Counting()
            Simulation.Start(counting)
            var p = new Gpio.Pin("sim", 9)
            p.Output(true)
            p.Write(false)
            var r = p.Read()
            print("touched " + counting.n + " times")
            Simulation.Stop()
            p.Write(true)
            print("after stop " + counting.n)
            // an RC low pass behind line 5, read back at line 6: the circuit runs in real time while the program waits
            var c = new Circuits.Circuit()
            c.TimeStep = 100us
            var out = c.Add(new Circuits.GpioLine(5))
            var back = c.Add(new Circuits.GpioLine(6))
            var res = c.Add(new Circuits.Resistor(10kOhm))
            var cap = c.Add(new Circuits.Capacitor(1uF))
            out.P.Connect(res.A)
            res.B.Connect(cap.A)
            cap.B.Connect(c.Ground)
            cap.A.Connect(back.P)
            c.RunAlongside(0.25)   // a quarter of real time: also a slow VM keeps up, so maxLag never skips
            print("alongside " + c.IsAlongside)
            var o = new Gpio.Pin("sim", 5)
            var i = new Gpio.Pin("sim", 6)
            o.Output(false)
            i.Input()
            Sleep(5)
            print("low at first " + !i.Read())
            o.Write(true)
            var start = c.TimeRaw()
            var t0 = DateTime.UtcNow.Ticks
            while (!i.Read() && DateTime.UtcNow.Ticks - t0 < 20000000) { Sleep(1) }
            var took = c.TimeRaw() - start
            print("rose " + i.Read() + ", after RC*ln2 or a little more: " + (took > 0.004 && took < 0.05))
            c.StopAlongside()
            print("alongside " + c.IsAlongside)
            """),
        ("Einheiten: eine Einheit, die eine reine Zahl wird (coerce to/from unitless, dB): mal/durch als Faktor, plus in dB, ohne Einheit gespeichert", """
            unit Decibel: dB {
                coerce to unitless => 10 ^ (value / 20)
                coerce from unitless => 20 * Math.Log10(value)
            }
            class H { static float R(float v) { return Math.Round(v * 1000) / 1000 } }
            class Box { float k
                construct(any v) { this.k = v } }
            var g = 6dB
            print(g)
            print(1V * g)
            print(10V / 20dB)
            print(3dB + 3dB)
            print(H.R(3dB * 1))
            float k : unitless = 20dB
            print(k + " " + 20dB:unitless + " " + new Box(40dB).k + " " + H.R(6dB))
            float:dB back = 2
            print(H.R(back / 1dB * 1))
            print(20dB > 6dB)
            """),
    }).ToArray();

    // TLS (packages/tls/native/fire_bridge_tls.h) and HTTPS: a certificate for localhost is made here (the tests trust exactly it); needs the development files of OpenSSL on this machine
    {
        bool hasOpenSsl = new[] { "/usr/include/openssl/ssl.h", "/usr/local/include/openssl/ssl.h", "/opt/homebrew/include/openssl/ssl.h", "/usr/include/x86_64-linux-gnu/openssl/ssl.h" }.Any(File.Exists);
        if (!hasOpenSsl)
        {
            Console.WriteLine("(Tls/Https: uebersprungen - die Entwicklerdateien von OpenSSL (openssl/ssl.h) sind auf diesem Rechner nicht da)");
        }
        else
        {
            using var rsa = System.Security.Cryptography.RSA.Create(2048);
            var request = new System.Security.Cryptography.X509Certificates.CertificateRequest("CN=localhost", rsa, System.Security.Cryptography.HashAlgorithmName.SHA256, System.Security.Cryptography.RSASignaturePadding.Pkcs1);
            var san = new System.Security.Cryptography.X509Certificates.SubjectAlternativeNameBuilder();
            san.AddDnsName("localhost");
            san.AddIpAddress(System.Net.IPAddress.Loopback);
            request.CertificateExtensions.Add(san.Build());
            request.CertificateExtensions.Add(new System.Security.Cryptography.X509Certificates.X509BasicConstraintsExtension(false, false, 0, true));
            using var certificate = request.CreateSelfSigned(DateTimeOffset.UtcNow.AddDays(-1), DateTimeOffset.UtcNow.AddYears(5));
            string FireText(string pem) => "\"" + pem.Replace("\r", "").Replace("\n", "\\n") + "\"";
            string certText = FireText(certificate.ExportCertificatePem()), keyText = FireText(rsa.ExportPkcs8PrivateKeyPem());
            string tlsHead = "#import \"tls\"\n#import \"http\"\n#import \"time\"\nvar certPem = " + certText + "\nvar keyPem = " + keyText + "\n";
            natCases = natCases.Concat(new (string Name, string Source)[]
            {
                ("Tls: Handshake, verschluesselte Daten, Zertifikatspruefung (unbekannt, falscher Name, ausgeschaltet) ueber Loopback", tlsHead + """
                    print("available " + Tls.Support.Available())
                    var probe = new Net.TcpListener("127.0.0.1", 0)
                    var port = probe.Port
                    probe.Close()
                    fire {
                        var l = new Net.TcpListener("127.0.0.1", port)
                        var server = new Tls.Server(certPem, keyPem)
                        var served = 0
                        while (served < 5) {
                            var tcp = l.TryAccept(10000)
                            if (tcp == undefined) { break }
                            served = served + 1
                            try {
                                var s = server.Accept(tcp, 5000)
                                var buf = new byte[64]
                                var n = s.Read(buf, 0, 64)
                                s.WriteString("echo:" + IO.Utf8.GetString(buf, 0, n))
                                s.Close()
                            } catch (Net.NetException e) { }
                        }
                        server.Close()
                        l.Close()
                    }
                    Sleep(400)
                    var o = new Tls.Options()
                    o.caPem = certPem
                    var s = Tls.Stream.Connect("localhost", port, o)
                    print("connected " + s.Info.StartsWith("TLSv1"))
                    s.WriteString("hello tls")
                    var buf = new byte[64]
                    var n = s.Read(buf, 0, 64)
                    print("got " + IO.Utf8.GetString(buf, 0, n))
                    print("eof " + s.Read(buf, 0, 64))
                    s.Close()
                    try { var t = Tls.Stream.Connect("localhost", port) } catch (Tls.CertificateException e) { print("untrusted " + e.code) }
                    var tcp2 = new Net.TcpClient("127.0.0.1", port)
                    try { var w = new Tls.Stream(tcp2, "wrong.example", o, 5000) } catch (Tls.CertificateException e) { print("wrong name " + e.code) }
                    var o2 = new Tls.Options()
                    o2.verify = false
                    var u = Tls.Stream.Connect("localhost", port, o2)
                    u.WriteString("unchecked")
                    var m = u.Read(buf, 0, 64)
                    print("unchecked " + IO.Utf8.GetString(buf, 0, m))
                    u.Close()
                    var tcp3 = new Net.TcpClient("127.0.0.1", port)
                    var v = new Tls.Stream(tcp3, "127.0.0.1", o, 5000)
                    v.WriteString("by ip")
                    var k = v.Read(buf, 0, 64)
                    print("by ip " + IO.Utf8.GetString(buf, 0, k))
                    Net.IConnection iv = v
                    iv.ReadTimeout = 3000
                    IO.IStream sv = iv
                    print("tls iconnection " + (v is of Net.IConnection) + " " + iv.RemoteHost + " " + (iv.RemotePort == port) + " " + (iv.LocalPort == v.LocalPort) + " " + v.LocalHost + " " + iv.ReadTimeout + " " + (sv is of Net.IConnection))
                    v.Close()
                    """),
                ("Https: Client und Server ueber TLS (https://-URL, Zertifikat des Tests, Zertifikatsfehler)", tlsHead + """
                    var probe = new Net.TcpListener("127.0.0.1", 0)
                    var port = probe.Port
                    probe.Close()
                    fire {
                        var server = new Http.Server("127.0.0.1", port)
                        server.UseTls(certPem, keyPem)
                        server.Route("GET", "/hello", func (r) => Http.Response.FromText("secure " + r.Query("name", "world")))
                        server.Route("POST", "/echo", func (r) => r.Text().ToUpper())
                        var served = 0
                        while (served < 4) {
                            if (server.ServeOne(10000)) { served = served + 1 }
                        }
                        server.Close()
                    }
                    Sleep(400)
                    var client = new Http.Client()
                    client.timeout = 10000
                    var o = new Tls.Options()
                    o.caPem = certPem
                    client.tls = o
                    var site = "https://localhost:" + port
                    var r1 = client.Get(site + "/hello?name=Anna")
                    print(r1.status + " [" + r1.Text() + "] " + r1.url.StartsWith("https://"))
                    var r2 = client.Post(site + "/echo", "grüß dich")
                    print(r2.status + " [" + r2.Text() + "]")
                    var strict = new Http.Client()
                    strict.timeout = 5000
                    try { strict.Get(site + "/hello") } catch (Tls.CertificateException e) { print("untrusted " + e.code) }
                    var loose = new Tls.Options()
                    loose.verify = false
                    strict.tls = loose
                    print(strict.Get(site + "/hello?name=loose").Text())
                    """),
            }).ToArray();
        }
    }

    // GPIO (packages/gpio/native/fire_bridge_gpio.h): the simulated chip "sim" - outputs, inputs, wires, pulls, edges, errors - the same in the VM and in the native build
    natCases = natCases.Concat(new (string Name, string Source)[]
    {
        ("Gpio: simulierter Chip - Ausgang, Eingang, Draht, Pull, Flanken, Fehler", """
            #import "gpio"
            print("chips " + Gpio.Board.Chips()[0] + " " + (Gpio.Board.Chips().Count >= 1))
            var led = new Gpio.Pin("sim", 1).Output()
            var btn = new Gpio.Pin("sim", 2).Input(Gpio.Pull.Down, Gpio.Edge.Both)
            print("props " + led.Chip + " " + led.Line + " " + led.IsOutput + " " + btn.IsInput + " " + led.IsClosed)
            Gpio.Sim.Wire(1, 2)
            print("low " + btn.Read() + " " + btn.ReadInt() + " " + led.Read())
            led.Write(true)
            print("high " + btn.Read() + " edge " + btn.TakeEdge())
            var first = btn.EdgeTime
            print("none " + btn.TakeEdge())
            print("toggle " + led.Toggle() + " " + btn.Read() + " edge " + btn.TakeEdge() + " " + (btn.EdgeTime >= first))
            Gpio.Sim.Unwire(1, 2)
            var up = new Gpio.Pin("sim", 3).Input(Gpio.Pull.Up, Gpio.Edge.Falling)
            print("pull up " + up.Read())
            Gpio.Sim.Drive(3, false)
            print("driven " + up.Read() + " " + Gpio.Sim.Level(3) + " edge " + up.WaitEdge(200ms))
            Gpio.Sim.Drive(3, true)
            print("rising is not watched: " + up.WaitEdge(30ms) + " " + up.Read())
            Gpio.Sim.Release(3)
            print("released " + up.Read())
            print("timeout " + up.WaitEdge(20))

            class Counter {
                int rising
                int falling
                construct() { this.rising = 0; this.falling = 0 }
                Count(e, t) {
                    if (e == Gpio.Edge.Rising) { this.rising = this.rising + 1 }
                    if (e == Gpio.Edge.Falling) { this.falling = this.falling + 1 }
                }
            }
            var counter = new Counter()
            var watch = new Gpio.Pin("sim", 4).Input(Gpio.Pull.None, Gpio.Edge.Both)
            watch.onEdge = (e, t) => { counter.Count(e, t) }
            for (var i = 0; i < 3; i++) {
                Gpio.Sim.Drive(4, true)
                Gpio.Sim.Drive(4, false)
            }
            print("poll " + watch.Poll() + " " + counter.rising + " " + counter.falling)
            for (var i = 0; i < 40; i++) { Gpio.Sim.Drive(4, i % 2 == 0) }
            print("queue " + watch.Poll())

            var out1 = new Gpio.Pin("sim", 5).Output(true)
            var out2 = new Gpio.Pin("sim", 6).Output(false)
            Gpio.Sim.Wire(5, 6)
            print("fight " + Gpio.Sim.Level(5) + " " + out1.Read() + " " + out2.Read())
            out2.Write(true)
            print("agree " + Gpio.Sim.Level(6))
            Gpio.Sim.Reset()

            try { var x = new Gpio.Pin("sim", 1).Input() } catch (Gpio.BusyException e) { print("busy " + e.code) }
            led.Close()
            var again = new Gpio.Pin("sim", 1).Output()
            print("reclaimed " + again.IsOutput)
            try { var x = new Gpio.Pin("sim", 99) } catch (Gpio.NotFoundException e) { print("no line " + e.code) }
            try { var x = new Gpio.Pin("nochip", 1) } catch (Gpio.NotFoundException e) { print("no chip " + e.code) }
            try { again.TakeEdge() } catch (Gpio.GpioException e) { print("output edge " + e.code) }
            try { btn.Write(true) } catch (Gpio.GpioException e) { print("input write " + e.code) }
            try { new Gpio.Pin("sim", 7).Read() } catch (Gpio.GpioException e) { print("unset " + e.code) }
            try { Gpio.Sim.Wire(1, 40) } catch (Gpio.NotFoundException e) { print("wire " + e.code) }
            try { led.Read() } catch (Gpio.GpioException e) { print("closed " + e.code) }
            """),
    }).ToArray();

    // Tracker (packages/tracker/native/fire_bridge_tracker.h): a module built in memory, rendered, played to the simulated audio device - the same in the VM and in the native build
    natCases = natCases.Concat(new (string Name, string Source)[]
    {
        ("Tracker: Modul im Speicher - Laden, Rendern, Seek, Mute, Stereo, Player auf dem simulierten Geraet, Fehler", """
            #import "tracker"

            // a module built in memory: one 4 channel pattern, a looped square wave as the only instrument
            var m = new byte[2172]
            m[0] = 102
            m[1] = 105
            m[2] = 114
            m[3] = 101
            m[20] = 115                  // sample name "s"
            m[43] = 32                   // 32 words = 64 bytes
            m[45] = 64                   // volume
            m[49] = 32                   // loop length: 32 words
            m[950] = 1                   // one position
            m[951] = 127
            m[1080] = 77
            m[1081] = 46
            m[1082] = 75
            m[1083] = 46                 // M.K.
            for (var i = 0; i < 64; i++) {
                if (i < 32) { m[2108 + i] = 100 } else { m[2108 + i] = 156 }
            }
            // row 0 channel 0: C-2 (period 428 = 0x1AC), sample 1
            m[1084] = 1
            m[1085] = 172
            m[1086] = 16
            // row 4 channel 1: E-2 (339 = 0x153), sample 1, volume 0x20 (C20)
            m[1084 + 16 * 4 + 4] = 1
            m[1084 + 16 * 4 + 5] = 83
            m[1084 + 16 * 4 + 6] = 28
            m[1084 + 16 * 4 + 7] = 32
            // row 8: D00 (pattern break) on channel 3 ends the pattern: 8 rows of 6 ticks at 125 bpm
            m[1084 + 8 * 16 + 12 + 2] = 13
            var song = Tracker.Song.Load(m)
            print("song " + song.Title + " " + song.Channels + " " + song.Orders + " " + song.Patterns + " " + song.Rate + " " + song.Milliseconds)
            print("state " + song.Order + " " + song.Row + " " + song.Speed + " " + song.Tempo + " " + song.Finished + " " + song.Loop + " " + song.Separation + " " + song.Interpolate + " " + song.Gain)
            print("sample " + song.SampleName(0) + " " + song.SampleLength(0) + " " + song.SampleVolume(0) + " " + song.SampleFinetune(0) + " " + song.SampleLoops(0) + " " + song.SampleLoops(1))
            print("cells " + song.CellText(0, 0, 0) + " | " + song.CellText(0, 4, 1) + " | " + song.CellText(0, 8, 3) + " | " + song.CellText(0, 1, 0))
            print("note names " + Tracker.Note.Name(428) + " " + Tracker.Note.Name(113) + " " + Tracker.Note.Name(0) + " " + Tracker.Note.Name(339))

            var rate = song.Rate
            var pcm = new byte[rate * 8]          // 2 seconds of stereo
            var n = song.Render(pcm, 0, rate * 2, 2)
            print("rendered " + n + " " + song.Finished + " " + song.Order + " " + song.Row)
            // left channel: channel 0 plays the 129 Hz square wave, the right one hears 1/3 of it (separation 50) plus channel 1 from row 4
            var peakL = 0
            var peakR = 0
            var crossings = 0
            var last = 0
            for (var f = 0; f < 13230; f++) {
                var l = pcm[f * 4] + pcm[f * 4 + 1] * 256
                if (l >= 32768) { l = l - 65536 }
                var r = pcm[f * 4 + 2] + pcm[f * 4 + 3] * 256
                if (r >= 32768) { r = r - 65536 }
                if (l > peakL) { peakL = l }
                if (r > peakR) { peakR = r }
                var sign = 1
                if (l < 0) { sign = -1 }
                if (f > 100 && sign != last) { crossings++ }
                last = sign
            }
            print("first 0.3 s: peak L " + peakL + " peak R " + peakR + " zero crossings " + crossings)
            var sum = 0
            for (var f = 0; f < n; f++) { sum = sum + pcm[f * 4] + pcm[f * 4 + 1] + pcm[f * 4 + 2] + pcm[f * 4 + 3] }
            print("checksum " + sum)
            print("after end " + song.Render(pcm, 0, 100, 2))

            song.Restart()
            print("restart " + song.Order + " " + song.Row + " " + song.Finished)
            print("seek " + song.Seek(0, 5) + " " + song.Order + " " + song.Row)
            print("channels " + song.ChannelPlaying(0) + " " + song.ChannelPlaying(1) + " " + song.ChannelVolume(0) + " " + song.ChannelVolume(1) + " " + song.ChannelSample(0))
            song.Restart()
            song.Mute(0)
            print("mute " + song.IsMuted(0) + " " + song.IsMuted(1))
            var quiet = new byte[rate * 4]
            song.Render(quiet, 0, 4410, 2)
            var max = 0
            for (var f = 0; f < 4410 * 4; f++) { if (quiet[f] > max) { max = quiet[f] } }
            print("muted silent " + (max == 0))
            song.Mute(0, false)

            song.Separation = 100
            song.Restart()
            var hard = new byte[rate * 4]
            song.Render(hard, 0, 4410, 2)
            var hardPeakR = 0
            for (var f = 2000; f < 4410; f++) {
                var r = hard[f * 4 + 2] + hard[f * 4 + 3] * 256
                if (r >= 32768) { r = r - 65536 }
                if (r > hardPeakR) { hardPeakR = r }
            }
            print("separation 100: right " + hardPeakR)
            song.Separation = 0
            song.Restart()
            song.Render(hard, 0, 4410, 2)
            var monoL = hard[8000] + hard[8001] * 256
            var monoR = hard[8002] + hard[8003] * 256
            print("separation 0: equal " + (monoL == monoR))
            song.Separation = 50
            song.Gain = 50
            song.Restart()
            song.Render(hard, 0, 4410, 2)
            var halfPeak = 0
            for (var f = 2000; f < 4410; f++) {
                var l = hard[f * 4] + hard[f * 4 + 1] * 256
                if (l >= 32768) { l = l - 65536 }
                if (l > halfPeak) { halfPeak = l }
            }
            print("gain 50: " + halfPeak)
            song.Gain = 100
            song.Interpolate = false
            print("interpolate " + song.Interpolate)
            song.Interpolate = true

            var whole = song.ToSound()
            print("sound " + whole.Rate + " " + whole.Channels + " " + whole.Milliseconds)
            var out = new Audio.Output("sim", rate, 2)
            var player = new Tracker.Player(song, out)
            song.Restart()
            player.Play()
            print("player " + Audio.Sim.Played() + " " + (Audio.Sim.Played() == whole.Length) + " " + player.Ended)
            out.Close()

            try { Tracker.Song.Load(pcm) } catch (Tracker.BadFormatException e) { print("bad " + e.code) }
            var shortFile = new byte[100]
            try { Tracker.Song.Load(shortFile) } catch (Tracker.TrackerException e) { print("short " + e.code) }
            var cut = new byte[1100]
            for (var i = 0; i < 1084; i++) { cut[i] = m[i] }
            cut[950] = 1
            try { Tracker.Song.Load(cut) } catch (Tracker.BadFormatException e) { print("truncated " + e.code) }
            m[1083] = 56
            m[1082] = 84
            m[1081] = 76
            m[1080] = 70                 // FLT8
            try { Tracker.Song.Load(m) } catch (Tracker.UnsupportedException e) { print("flt8 " + e.code) }
            song.Close()
            try { song.Order } catch (Tracker.TrackerException e) { print("closed " + e.code) }
            """),
    }).ToArray();

