                        int n = Http.Num.Parse(s.Get("n", "0")) + 1
                        s.Set("n", n)
                        return Http.Response.FromText("n=" + n)
                    }
                    if (path == "/login") { s.Set("user", "anna"); s.Renew(); return Http.Response.FromText("welcome " + s.Get("user")) }
