                out = out + r.Text() + " cookie " + cookie.StartsWith("fire-session=") + " " + (cookie.IndexOf("HttpOnly") > 0) + "\n"
                var h = new Http.Headers()
                h.Set("Cookie", "theme=dark; fire-session=" + id)
