                    try { any mine = take note } catch (AccessDeniedException e) { line = line + " take denied" }
                    finished.Send(line)
                    ch.Send(job.n * 2)
                    any go = ch.Receive()
                    try { finished.Send("thread " + go + " " + note.text) } catch (DestroyedException e) { finished.Send("thread " + go + ": the note ended with its owner") }
                    ch.Send("bye")
                    ch.Close()
                    any rest = ch.Receive()
