                    var words16Lines = new List<string>();
                    string words16Script = "#import \"pkwords\"\nword w[] = [1, 2, 65535]\nprint(PkWords.Sum(w) + \" \" + PkWords.Inc(w) + \" \" + w[0] + \" \" + w[2] + \" \" + Word.Bits)\n";
